  om2 = p7_oprofile_Create(om1->M, om1->abc);
  om2->M = M;
  esl_strdup(om1->name, -1, &om2->name);

  memcpy(om2->tscf, om1->tscf, sizeof(float) * p7O_NQF * p7_NTRANS);

  for(i = 0; i < p7O_NQB; i++) {
