static uint8_t
biased_byteify(P7_OPROFILE *om, float sc)
{
  int32_t b;
  b = round(om->offs[om->mode] + sc * om->scale_b);
  b = ESL_MAX(b, 0);
  b = ESL_MIN(b, 255);
  return (uint8_t) b;
}

static uint8_t
unbiased_byteify(P7_OPROFILE *om, float sc)
{
  int32_t b;
  b = round(om->base_b + sc * om->scale_b);
  b = ESL_MAX(b, 0);
  b = ESL_MIN(b, 255);
  return (uint8_t) b;
}

static int16_t
wordify(P7_OPROFILE *om, float sc)
{
  int32_t w;
  w = round(om->base_w + sc * om->scale_w);
  w = ESL_MAX(w, -32768);
  w = ESL_MIN(w,  32767);
  return (int16_t) w;
}

static int
sf_conversion(P7_OPROFILE *om)
{
  om->ncj_b = log( (float) om->L / (float) (om->L+3) ) * om->scale_b;
  om->ecj_b = log( 2.0 / ((float)om->L * (float)(om->L+1)) ) * om->scale_b;

  return eslOK;
}

