static int
fb_conversion(const P7_PROFILE *gm, P7_OPROFILE *om)
{
  int k, x;
  int i,j;
  float *tp;
  float *rp;

  om->M = gm->M;
  esl_strdup(gm->name, -1, &(om->name));

  tp = om->tscf;
  for(i=0; i<p7O_NQF; i++) {
    for(j=0; j<p7_NTRANS; j++) {
      *tp = 0;
      tp++;
    }
  }

  for (k = 0; k <= gm->M; k++) {
    for (x = 0; x < gm->abc->K; x++) {
      om->rscf[k%p7O_NQB][(k/p7O_NQB)*gm->abc->K+x] = gm->rsc[k][x];
