  return eslOK;

 ERROR:
  return status;
}

int
p7_omx_FDeconvert(P7_OMX *ox, P7_GMX *gx)
{
  int i,k;
  for (i = 0; i <= gx->L; i++) {
    for (k = 0; k <= gx->M; k++) {
      gx->dp[i][k][p7G_M] = p7_omx_FGetMDI(ox, p7X_M, i, k);
      gx->dp[i][k][p7G_I] = p7_omx_FGetMDI(ox, p7X_I, i, k);
      gx->dp[i][k][p7G_D] = p7_omx_FGetMDI(ox, p7X_D, i, k);
    }
  }
  return eslOK;
}

int
p7_omx_Reuse(P7_OMX *ox)
{
  ox->M = 0;
  ox->L = 0;
  ox->validM = 0;
  ox->validL = 0;
  return eslOK;
}


