p7_omx_Destroy(P7_OMX *ox)
{
  if (ox == NULL) return;
  if (ox->dpf  != NULL) free(ox->dpf);
  if (ox->dpw  != NULL) free(ox->dpw);
  if (ox->dpc  != NULL) free(ox->dpc);
  if (ox->dumper != NULL) free(ox->dumper);
  free(ox);
}
