p7_BackwardParser(const ESL_DSQ *dsq, int L, const P7_OPROFILE *om, const P7_OMX *fwd, P7_OMX *bck, float *opt_sc)
{
  return backward_engine(FALSE, dsq, L, om, fwd, bck, opt_sc);
}


static int
forward_engine(int do_full, const ESL_DSQ *dsq, int L, const P7_OPROFILE *om, P7_OMX *ox, float *opt_sc)
{
  int i, k;

  p7_omx_FSetMDI(ox, p7X_M, 0, 0, 0.0f);
  p7_omx_FSetMDI(ox, p7X_I, 0, 0, -HUGE_VALF);
  p7_omx_FSetMDI(ox, p7X_D, 0, 0, -HUGE_VALF);

  for (k = 1; k <= om->M; k++) {
      p7_omx_FSetMDI(ox, p7X_M, 0, k, -HUGE_VALF);
      p7_omx_FSetMDI(ox, p7X_I, 0, k, -HUGE_VALF);
      p7_omx_FSetMDI(ox, p7X_D, 0, k, -HUGE_VALF);
  }

  for (i = 1; i <= L; i++)
  {
    for (k = 1; k <= om->M; k++)
    {
        float m_sc = p7_omx_FGetMDI(ox, p7X_M, i-1, k-1);
        float i_sc = p7_omx_FGetMDI(ox, p7X_I, i-1, k-1);
        float d_sc = p7_omx_FGetMDI(ox, p7X_D, i-1, k-1);

        float path_max = (m_sc > i_sc ? m_sc : i_sc);
        path_max = (path_max > d_sc ? path_max : d_sc);

        p7_omx_FSetMDI(ox, p7X_M, i, k, path_max + p7_oprofile_FGetEmission(om, k, dsq[i]));
        p7_omx_FSetMDI(ox, p7X_I, i, k, -HUGE_VALF);
        p7_omx_FSetMDI(ox, p7X_D, i, k, -HUGE_VALF);
    }
  }

  *opt_sc = -HUGE_VALF;
  for (k = 1; k <= om->M; k++) {
    if (p7_omx_FGetMDI(ox, p7X_M, L, k) > *opt_sc) *opt_sc = p7_omx_FGetMDI(ox, p7X_M, L, k);
  }
  return eslOK;
}

static int
backward_engine(int do_full, const ESL_DSQ *dsq, int L, const P7_OPROFILE *om, const P7_OMX *fwd, P7_OMX *bck, float *opt_sc)
{
    return eslOK;
}
